import React from 'react'
import PropTypes from 'prop-types'
import {
  ContainerLayout,
  ContainerBody
} from './index.style'
import { Row, Col, Form, Button, Modal, Alert, Select, Checkbox } from 'antd'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import CircularLoader from '../../../../../components/CircularLoader'
import { ERROR_STRINGS, LANG_STRINGS } from '../../../../../constants/lang'
import policyAction from '../../../../../redux/lazadaCrackScreenEndorse/actions'
import { getFormItems, errorHandler } from '../../../../../components/utility/formItems'
import { LAZADA_HOSPITAL_CASH_PLAN } from '../../../constants'
import _ from 'lodash'
import { CLOSE_ICON } from '../../../../../constants/icons'
import validator from '../../../../../helpers/validator'
import IntlMessages from '../../../../../components/utility/intlMessages'
import EndorseWelcome from '../../../LazadaCrackScreenEndorsement/components/LazadaCrackScreenEndorsementThankYou'
import { firstPopup, secondPopup } from './constants/index'
const { getLazadaHospitalCashPlanPolicyDetails, resetLazadaEndorseData, postLazadaCrackScreenEndorse, getProvinceData } = policyAction
const summaryPdfUrl = 'https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/Ringkasan%20Produk%20MyHealth%20Protection%20CashPlus.pdf'
class LazadaHospitalCashPlanEndorsement extends React.PureComponent {
  constructor (props) {
    super(props)
    this.state = {
      insuredFieldDisabled: false,
      buttonDisabled: true,
      checkbox1: false,
      checkbox2: false,
      modalShow: false,
      modalTitle: ''
    }
  }
  static defaultProps = {
    lazadahcpProvinceData: []
  }
  static propTypes = {
    id: PropTypes.string,
    lazadahcpProvinceData: PropTypes.arrayOf(PropTypes.object)
  }
  componentWillReceiveProps (nextProps) {
    const { submitSendoError, gosureDetailsMessage } = nextProps
    errorHandler.call(this, {
      submitError: submitSendoError,
      detailMessage: gosureDetailsMessage,
      resetFunction: () => this.props.resetLazadaEndorseData(['postLazadaCrackScreenEndorseMessage'])
    })
  }
  componentDidMount () {
    const { id } = this.props
    this.props.getLazadaHospitalCashPlanPolicyDetails({ query: { id } })
    this.props.getProvinceData()
  }
  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }
  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }
  showErrorMessage = () => {
    return <Alert
      message={<IntlMessages id={ERROR_STRINGS.error} />}
      description={<IntlMessages id={ERROR_STRINGS.serverError} />}
      type='error'
    />
  }

  openModalData = (val = '') => {
    switch (val) {
      case 'Syarat & Ketentuan':
        this.setState({
          modalShow: !this.state.modalShow,
          checkbox1: !this.state.checkbox1,
          modalTitle: val
        })
        break
      case 'Deklarasi Kesehatan':
        this.setState({
          modalShow: !this.state.modalShow,
          checkbox2: !this.state.checkbox2,
          modalTitle: val
        })
        break
      default: {
        this.setState({
          modalShow: !this.state.modalShow,
          modalTitle: val
        })
      }
    }
  }

  handleFormSubmit = async (e) => {
    e.preventDefault()
    const { form } = this.props
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const formBody = form.getFieldsValue()
    const body = {
      ...formBody,
      dob: formBody.dob.format('YYYY-MM-DD'),
      phone_no: `62${formBody.phone_no}`
    }
    this.props.postLazadaCrackScreenEndorse({ body, params: { id: this.props.id } })
  }
  checkBoxHandler = (e, value) => {
    if (value === 'first') {
      this.setState({
        checkbox1: e.target.checked
      })
    } else {
      this.setState({
        checkbox2: e.target.checked
      })
    }
  }
  render () {
    const { modalShow, modalTitle, checkbox1, checkbox2 } = this.state
    const {
      form,
      policyDetailLoading, detailsData, submitSendoLoading,
      policyDetailError, gosureDetailsMessage, lazadahcpProvinceDataLoading, lazadahcpProvinceData
    } = this.props
    const { getFieldDecorator } = form
    const isSuccessFulEndorse = (gosureDetailsMessage === 'success') ||
      (_.get(detailsData, 'detail.EndorsementStatus', '') === 'SUCCESS')
    return (
      <ContainerLayout>
        {
          isSuccessFulEndorse ? <EndorseWelcome /> : policyDetailError ? this.showErrorMessage()
            : <CircularLoader isSpining={policyDetailLoading || submitSendoLoading}>
              <ContainerBody>
                <Modal
                  className='lazadahcpModal'
                  closable
                  visible={modalShow}
                  footer={null}
                  closeIcon={
                    <div className='close-icon-cont'>
                      <img className='close-icon' src={CLOSE_ICON} alt='close-icon' />
                    </div>
                  }
                  onCancel={() => this.openModalData('')}
                >
                  <React.Fragment>

                    <div className='heading-container'>
                      <div className='text-container-div'>
                        <p className='text-container'><IntlMessages id={modalTitle} /></p>
                      </div>
                    </div>
                    <Row className='body-container-style' type='flex' justify='center'>
                      <Col span={20}>
                        <div className='list-container-style'>
                          <ol className='order-custom-style'>
                            {
                              modalTitle === 'Syarat & Ketentuan'
                                ? firstPopup.map((item, index) => <li className='list-custom-style' key={index}><p><IntlMessages id={item} /></p></li>)
                                : secondPopup.map((item, index) => <li className='list-custom-style' key={index}><p><IntlMessages id={item} /></p></li>)
                            }
                            {
                              modalTitle === 'Syarat & Ketentuan' &&
                              <React.Fragment>
                                <p className='tnc-modal-footer-heading'><IntlMessages id='Ringkasan Produk' /></p>
                                <p className='tnc-modal-footer-content'><IntlMessages id='Baca Ringkasan Produk' /> : <a href={summaryPdfUrl} target='_blank' rel='noopener noreferrer'><IntlMessages id='Klik Disini' /></a></p>
                              </React.Fragment>
                            }
                          </ol>
                        </div>
                      </Col>
                    </Row>
                  </React.Fragment>
                </Modal>
                <h3 className='form-heading'><IntlMessages id='Aktivasi Asuransi Perlindungan Rawat Inap' /></h3>
                <p className='form-subheading'><IntlMessages id='Aktifkan Asuransi Perlindungan Rawat Inap dengan mengisi rincian informasi data diri secara benar. Jika informasi data diri Anda tidak benar, maka manfaat dari polis tidak dapat diklaim.' /></p>
                <Form onSubmit={this.handleFormSubmit}>
                  <Row>
                    {
                      LAZADA_HOSPITAL_CASH_PLAN.map(val =>
                        <Col>
                          {getFormItems.call(this, val)}
                        </Col>
                      )
                    }
                    <Col>
                      <Form.Item label={this.intlText({ id: 'Provinsi' })}>
                        {getFieldDecorator('province', {
                          rules: [
                            {
                              required: true,
                              message: (<IntlMessages id={LANG_STRINGS.requiredField} />)
                            },
                            { validator: validator.checkValidator }
                          ]

                        })(
                          <Select
                            // disabled={disableField}
                            loading={lazadahcpProvinceDataLoading}
                            showSearch
                            placeholder={this.intlText({ id: 'Province' })}
                            style={{ width: '100%' }}
                            filterOption={(input, option) =>
                              option.props.children
                                .toLowerCase()
                                .indexOf(input.toLowerCase()) >= 0
                            }
                            className='width-100'
                          >
                            {
                              lazadahcpProvinceData.length > 0 &&
                              lazadahcpProvinceData.map((option, index) => {
                                return (
                                  <Select.Option key={index} value={option.province_name}>
                                    {option.province_name}
                                  </Select.Option>
                                )
                              })
                            }
                          </Select>)
                        }
                      </Form.Item>
                    </Col>
                  </Row>
                  <Row type='flex'>
                    <Col span={24}>
                      <p>
                        <Checkbox onChange={(e) => this.checkBoxHandler(e, 'first')}>
                          <IntlMessages id='Saya telah membaca, mengerti, dan setuju pada' />
                          <span className='modal-link' onClick={() => this.openModalData('Syarat & Ketentuan')}><IntlMessages id=' syarat & ketentuan' /> </span>
                          <IntlMessages id=' dan kebijakan privasi yang berlaku.' />
                        </Checkbox>
                      </p>
                    </Col>
                  </Row>
                  <Row type='flex'>
                    <Col span={24}>
                      <p>
                        <Checkbox onChange={(e) => this.checkBoxHandler(e, 'second')}>
                          <IntlMessages id='Saya menyatakan bahwa saya secara fisik dalam keadaan sehat dan setuju dengan' />
                          <span className='modal-link' onClick={() => this.openModalData('Deklarasi Kesehatan')}><IntlMessages id=' Deklarasi Kesehatan' /> </span>
                        </Checkbox>
                      </p>
                    </Col>
                  </Row>

                  <Row type='flex' justify='center' className='submit-button'>
                    <Col className='bottom-form'>
                      <Button
                        disabled={!(checkbox2 && checkbox1)}
                        type='primary'
                        className='form-btn'
                        htmlType='submit'
                        key='submit'
                      >
                        <IntlMessages id='Kirim' />
                      </Button>
                    </Col>
                  </Row>
                </Form>
              </ContainerBody>
            </CircularLoader>
        }
      </ContainerLayout>
    )
  }
}
const LazadaHospitalCashPlanEndorsementWrapped = Form.create()(LazadaHospitalCashPlanEndorsement)
export default connect(
  state => ({
    lazadahcpProvinceData: state.LazadaCrackScreen.lazadahcpProvinceData,
    lazadahcpProvinceDataLoading: state.Loading.GET_PROVINCE_DATA,
    detailsData: state.LazadaCrackScreen.lazadaPolicyDetails,
    policyDetailLoading: state.Loading.GET_LAZADA_HOSPITAL_CASH_PLAN_POLICY_DETAIL,
    policyDetailError: state.Error.GET_LAZADA_HOSPITAL_CASH_PLAN_POLICY_DETAIL,
    gosureDetailsMessage: state.LazadaCrackScreen.postLazadaCrackScreenEndorseMessage,
    submitSendoLoading: state.Loading.POST_LAZADA_POLICY_DETAIL,
    submitSendoError: state.Error.POST_LAZADA_POLICY_DETAIL
  }), {
    getLazadaHospitalCashPlanPolicyDetails, resetLazadaEndorseData, postLazadaCrackScreenEndorse, getProvinceData
  }
)(injectIntl(LazadaHospitalCashPlanEndorsementWrapped))
